 const blue=new T.MeshLambertMaterial({color:'#31596d'}),metal=new T.MeshLambertMaterial({color:'#a8b6b5'}),yellow=new T.MeshBasicMaterial({color:'#f5de67',transparent:true,opacity:.7,depthWrite:false,side:T.DoubleSide,polygonOffset:true,polygonOffsetFactor:-5}),target=new T.Mesh(new T.PlaneGeometry(3.1,12),yellow);target.rotation.x=-Math.PI/2;group.add(target);
 for(const [i,s]of route.stops.entries()){s.y=world.walkHeight(s.x,s.z);const verge=s.edge.r.width/2+.75,lane=Math.min(s.edge.r.width*.23,2.5);s.curb={x:s.x+s.dz*(verge-lane),z:s.z-s.dx*(verge-lane)};const y=world.walkHeight(s.curb.x,s.curb.z),pole=new T.Mesh(new T.CylinderGeometry(.04,.05,2.65,6),metal);pole.position.set(s.curb.x,y+1.325,s.curb.z);group.add(pole);const canvas=document.createElement('canvas');canvas.width=128;canvas.height=160;const c=canvas.getContext('2d');c.fillStyle='#275266';c.fillRect(0,0,128,160);c.fillStyle='#f6f0d5';c.font='bold 42px sans-serif';c.textAlign='center';c.fillText('BUS',64,57);c.font='bold 29px sans-serif';c.fillText('W01',64,104);c.font='20px sans-serif';c.fillText(String(i+1)+' / '+route.stops.length,64,140);const map=new T.CanvasTexture(canvas);map.colorSpace=T.SRGBColorSpace;const sign=new T.Mesh(new T.PlaneGeometry(.55,.7),new T.MeshLambertMaterial({map,side:T.DoubleSide}));sign.position.set(s.curb.x,y+2.35,s.curb.z);sign.rotation.y=s.yaw;group.add(sign);}
