 const s=route.stops[state.index],bus=state.bus,p=bus.position,distance=Math.hypot(p.x-s.x,p.z-s.z),remaining=s.due-state.elapsed;let action=bus.inWater||bus.engineFlooded?'Recover your bus with R':driving.vehicle!==bus?'Return to your route bus':state.eligible?`Boarding ${state.boarded}/${s.waiting} · keep stopped`:distance<12?'Stop facing the route and hold SPACE':'Follow the yellow route';const text=`W01 · WAINUI VILLAGE LOCAL · ${state.index+1}/${route.stops.length}\n${s.name}\n${Math.round(distance)}m · ${action}\nOn board ${state.onboard.length} · Delivered ${state.delivered} · ${remaining>=0?'Due in '+time(remaining):'Late '+time(-remaining)}\nTrip ${time(state.elapsed)} · ${state.score} points`;if(text!==previousHud)hud.textContent=previousHud=text;
