 for(let i=state.index;i<route.stops.length;i++){const stop=route.stops[i];if(Math.hypot(stop.x-camera.x,stop.z-camera.z)>240)continue;const boarded=i===state.index?state.boarded:0;for(let n=boarded;n<stop.waiting;n++){const along=3.8-(n-boarded)*.85;let x=stop.curb.x+stop.dx*along,z=stop.curb.z+stop.dz*along,walk=false;if(i===state.index&&n===boarded&&state.eligible&&state.dwell>1){const t=Math.max(0,Math.min(1,(state.dwell-1)/.9-state.boarded));const doorX=p.x+s.dx*3.8+s.dz*1.35,doorZ=p.z+s.dz*3.8-s.dx*1.35;x+=(doorX-x)*t;z+=(doorZ-z)*t;walk=t>0}pose(x,z,stop.yaw,i*11+n+901,walk)}}
